import SwiftUI

extension SwiftForgeTheme {

    /// Warm and expressive: golden-hour buttons that fade from magenta to
    /// ember orange, on apricot-cream surfaces by day and dusk-plum ones at
    /// night.
    ///
    /// Shadows glow warm instead of falling gray — ember-tinted in light
    /// mode, a faint magenta halo in dark mode, where black shadows would
    /// vanish into the plum canvas. Headings are heavy and rounded while
    /// body text stays plain for long reading. Corners are softly rounded
    /// (12-pt controls, 18-pt cards), chips are pills, and motion has a
    /// lively spring.
    public static let sunset: SwiftForgeTheme = {
        typealias P = Palette.Sunset
        let accent = SwiftForgeToneColors(
            solid: SwiftForgeColor(
                light: P.Magenta.s600, dark: P.Magenta.s300, lightHighContrast: P.Magenta.s800, darkHighContrast: P.Magenta.s200),
            onSolid: SwiftForgeColor(light: Palette.white, dark: P.plum, darkHighContrast: Palette.black),
            text: SwiftForgeColor(
                light: P.Magenta.s700, dark: P.Magenta.s300, lightHighContrast: P.Magenta.s800, darkHighContrast: P.Magenta.s200),
            subtle: SwiftForgeColor(
                light: P.Magenta.s50, dark: P.Magenta.s950, lightHighContrast: P.Magenta.s100, darkHighContrast: P.Magenta.s900),
            solidFill: .linearGradient(
                [
                    SwiftForgeColor(
                        light: P.Magenta.s600, dark: P.Magenta.s300, lightHighContrast: P.Magenta.s800,
                        darkHighContrast: P.Magenta.s200),
                    SwiftForgeColor(
                        light: P.Ember.s600, dark: P.Ember.s300, lightHighContrast: P.Ember.s800, darkHighContrast: P.Ember.s200),
                ], startPoint: .leading, endPoint: .trailing))
        let colors = SwiftForgeColors(
            canvas: SwiftForgeColor(light: P.cream, dark: P.plum),
            surface: SwiftForgeColor(light: Palette.white, dark: P.plumPanel),
            surfaceRaised: SwiftForgeColor(light: Palette.white, dark: P.plumLift),
            fillMuted: SwiftForgeColor(
                light: P.Dune.s100, dark: P.Dune.s900, lightHighContrast: P.Dune.s200, darkHighContrast: P.Dune.s800),
            textPrimary: SwiftForgeColor(
                light: P.ink, dark: P.glow, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            textSecondary: SwiftForgeColor(
                light: P.Dune.s700, dark: P.Dune.s300, lightHighContrast: P.Dune.s800, darkHighContrast: P.Dune.s200),
            borderSubtle: SwiftForgeColor(
                light: P.Dune.s200, dark: P.Dune.s800, lightHighContrast: P.Dune.s400, darkHighContrast: P.Dune.s600),
            borderStrong: SwiftForgeColor(
                light: P.Dune.s500, dark: P.Dune.s500, lightHighContrast: P.Dune.s700, darkHighContrast: P.Dune.s300),
            focusRing: accent.text,
            pressedOverlay: SharedTokens.pressedOverlay,
            accent: accent,
            neutral: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Dune.s800, dark: P.Dune.s300, lightHighContrast: P.Dune.s900, darkHighContrast: P.Dune.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.plum, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Dune.s700, dark: P.Dune.s300, lightHighContrast: P.Dune.s800, darkHighContrast: P.Dune.s200),
                subtle: SwiftForgeColor(
                    light: P.Dune.s100, dark: P.Dune.s900, lightHighContrast: P.Dune.s200, darkHighContrast: P.Dune.s800)),
            info: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Dusk.s700, dark: P.Dusk.s300, lightHighContrast: P.Dusk.s800, darkHighContrast: P.Dusk.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.plum, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Dusk.s700, dark: P.Dusk.s300, lightHighContrast: P.Dusk.s800, darkHighContrast: P.Dusk.s200),
                subtle: SwiftForgeColor(
                    light: P.Dusk.s50, dark: P.Dusk.s950, lightHighContrast: P.Dusk.s100, darkHighContrast: P.Dusk.s900)),
            success: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Palm.s700, dark: P.Palm.s300, lightHighContrast: P.Palm.s800, darkHighContrast: P.Palm.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.plum, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Palm.s700, dark: P.Palm.s300, lightHighContrast: P.Palm.s800, darkHighContrast: P.Palm.s200),
                subtle: SwiftForgeColor(
                    light: P.Palm.s50, dark: P.Palm.s950, lightHighContrast: P.Palm.s100, darkHighContrast: P.Palm.s900)),
            warning: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Gold.s300, dark: P.Gold.s300, lightHighContrast: P.Gold.s400, darkHighContrast: P.Gold.s200),
                onSolid: SwiftForgeColor(
                    light: P.ink, dark: P.plum, lightHighContrast: Palette.black, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Gold.s700, dark: P.Gold.s300, lightHighContrast: P.Gold.s800, darkHighContrast: P.Gold.s200),
                subtle: SwiftForgeColor(
                    light: P.Gold.s50, dark: P.Gold.s950, lightHighContrast: P.Gold.s100, darkHighContrast: P.Gold.s900)),
            danger: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Crimson.s700, dark: P.Crimson.s400, lightHighContrast: P.Crimson.s800,
                    darkHighContrast: P.Crimson.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.plum, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Crimson.s700, dark: P.Crimson.s400, lightHighContrast: P.Crimson.s800,
                    darkHighContrast: P.Crimson.s200),
                subtle: SwiftForgeColor(
                    light: P.Crimson.s50, dark: P.Crimson.s950, lightHighContrast: P.Crimson.s100,
                    darkHighContrast: P.Crimson.s900))
        )
        return SwiftForgeTheme(
            id: "sunset",
            displayName: "Sunset",
            colors: colors,
            typography: SwiftForgeTypography.standard
                .updating([\.largeTitle, \.title1, \.title2, \.title3]) {
                    $0.design = .rounded
                    $0.weight = .heavy
                }
                .updating([\.headline, \.controlLabel, \.controlLabelSmall, \.badge]) {
                    $0.design = .rounded
                    $0.weight = .bold
                },
            radius: SwiftForgeRadius(
                xs: 4, sm: 6, md: 10, lg: 14, xl: 18, xxl: 24,
                control: 12, controlSmall: 8, card: 18, sheet: 24
            ),
            elevation: SwiftForgeElevation(
                low: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Ember.s600, 0.16, dark: P.Magenta.s300, 0.12), radius: 6, y: 3),
                medium: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Ember.s600, 0.18, dark: P.Magenta.s300, 0.18), radius: 18, y: 8),
                high: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Magenta.s700, 0.22, dark: P.Magenta.s300, 0.24), radius: 36, y: 16),
                raisedSurfacesHaveBorder: false
            ),
            motion: SwiftForgeMotion(
                fast: SwiftForgeMotionToken(duration: 0.2, bounce: 0.15),
                standard: SwiftForgeMotionToken(duration: 0.32, bounce: 0.12),
                emphasized: SwiftForgeMotionToken(duration: 0.45, bounce: 0.22),
                shimmerDuration: 1.4,
                pressedScale: 0.96
            ),
            components: SwiftForgeComponentTokens(
                button: SwiftForgeButtonTokens(elevation: .low),
                banner: SwiftForgeBannerTokens(cornerRadius: 18),
                chip: SwiftForgeChipTokens(cornerRadius: SwiftForgeRadius.capsule),
                slider: SwiftForgeSliderTokens(trackHeight: 6, thumbDiameter: 26),
                avatar: SwiftForgeAvatarTokens(ringWidth: 3),
                emptyState: SwiftForgeEmptyStateTokens(iconSize: 56)
            )
        )
    }()
}
